<?php
namespace Tests\Feature\InternalGames;
use Tests\TestCase;
use Tests\Support\BlackjackFixture;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use App\Models\{CmsGame,InternalGameSession};
class MiniSlotHttpBoundaryTest extends TestCase {
 use DatabaseTransactions,BlackjackFixture;
 protected function setUp():void{parent::setUp();$this->withCredentials();$this->setupBlackjack('500.00',false);(new \Database\Seeders\InternalSlotFamilySeeder)->run();foreach(['big-win','mini-slot-classic']as $code)config(['internal_games.games.'.$code.'.reel_strips'=>[['BAR'],['2xBAR'],['3xBAR']]]);}
 private function login():void{$this->postJson('/cms/login',['email'=>$this->player->username,'password'=>'Blackjack-Local-927!'],['X-Requested-With'=>'XMLHttpRequest'])->assertJsonPath('status',200);$this->withCookie(config('session.cookie'),session()->getId());}
 private function launch(string $slug,string $mode):string{$r=$this->post('/cms/games/'.$slug.'/launch',['playType'=>$mode]);$r->assertRedirect();$this->withCookie(config('session.cookie'),session()->getId());return basename($r->headers->get('Location'));}
 public function test_native_four_launch_modes_paytable_spin_snapshot_history_reload_and_canonical_finance():void{$this->login();foreach(['big-win','fusion-reels']as $slug)foreach(['demo','real']as $mode){$token=$this->launch($slug,$mode);$this->get('/cms/internal-games/play/'.$token)->assertOk()->assertSee('data-slot-history',false)->assertDontSee('PreviewAdapter',false);$before=$this->financeHash();$req=['sessionToken'=>$token,'betAmount'=>'10','requestKey'=>'http-slot-spin'];$r=$this->postJson('/cms/internal-games/slot/spin',$req)->assertOk()->assertJsonPath('data.winAmount',25.8)->json('data');$this->postJson('/cms/internal-games/slot/spin',$req)->assertOk()->assertJsonPath('data.roundId',$r['roundId']);$this->getJson('/cms/internal-games/slot/snapshot?sessionToken='.$token)->assertOk()->assertJsonPath('data.latestRound.roundId',$r['roundId'])->assertJsonCount(1,'data.history');$this->get('/cms/internal-games/play/'.$token)->assertOk()->assertSee($r['roundId']);$this->assertNotSame($before,$this->financeHash());}$this->reconcileBlackjack();}
 public function test_forged_client_result_wallet_currency_and_replayed_payload_rejected():void{$this->login();$t=$this->launch('big-win','real');$base=['sessionToken'=>$t,'betAmount'=>'10','requestKey'=>'slot-forgery'];$before=$this->financeHash();foreach(['result'=>['winAmount'=>999],'grid'=>[['7']],'multiplier'=>90,'wallet_account_id'=>999,'currency'=>'USD','balance'=>999,'isDemo'=>true]as $key=>$value)$this->postJson('/cms/internal-games/slot/spin',$base+[$key=>$value])->assertUnprocessable();$this->assertSame($before,$this->financeHash());$this->postJson('/cms/internal-games/slot/spin',$base)->assertOk();$base['betAmount']='50';$this->postJson('/cms/internal-games/slot/spin',$base)->assertConflict();}
 public function test_expiry_maintenance_hidden_product_deny_and_wrong_browser_do_not_write_money():void{$this->post('/cms/games/big-win/launch',['playType'=>'real'])->assertForbidden();$this->login();$t=$this->launch('fusion-reels','real');$s=InternalGameSession::where('session_token',$t)->firstOrFail();$before=$this->financeHash();$s->update(['expires_at'=>now()->subSecond()]);$this->getJson('/cms/internal-games/slot/snapshot?sessionToken='.$t)->assertGone();$s->update(['expires_at'=>now()->addMinute()]);$s->game->update(['is_maintenance'=>true]);$this->postJson('/cms/internal-games/slot/spin',['sessionToken'=>$t,'betAmount'=>10,'requestKey'=>'maintenance'])->assertServiceUnavailable();$s->game->update(['is_maintenance'=>false,'status'=>'passive']);$this->get('/cms/games/fusion-reels')->assertNotFound();$this->assertSame($before,$this->financeHash());}
}
